"use client"
import Link from "next/link"
import { usePathname } from "next/navigation"
import { Home, Grid3x3, Newspaper, AlertTriangle, User } from "lucide-react"
import { useAuth } from "@/contexts/auth-context"

export function BottomNav() {
  const pathname = usePathname()
  const { isAuthenticated } = useAuth()

  const navItems = [
    { icon: Home, label: "Home", href: "/", authRequired: false },
    { icon: Grid3x3, label: "Services", href: "/services", authRequired: false },
    { icon: Newspaper, label: "News", href: "/news", authRequired: false },
    { icon: AlertTriangle, label: "Emergency", href: "/emergency", authRequired: false },
    { icon: User, label: "Account", href: isAuthenticated ? "/account" : "/login", authRequired: false },
  ]

  return (
    <nav className="lg:hidden fixed bottom-0 left-0 right-0 bg-white border-t border-gray-200 px-4 py-3 z-50">
      <div className="flex items-center justify-around max-w-md mx-auto">
        {navItems.map((item) => {
          const isActive = pathname === item.href
          return (
            <Link key={item.href} href={item.href} className="flex flex-col items-center gap-1">
              <item.icon className={`w-6 h-6 ${isActive ? "text-orange-500" : "text-gray-400"}`} />
              <span className={`text-xs ${isActive ? "text-orange-500 font-semibold" : "text-gray-500"}`}>
                {item.label}
              </span>
            </Link>
          )
        })}
      </div>
    </nav>
  )
}
